// src/services/api.js
const BASE_URL = '';  // foloseşte proxy-ul CRA din package.json

async function request(path, options = {}) {
  const res = await fetch(path, {
    credentials: 'include',                // dacă foloseşti cookie-uri de sesiune
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });
  if (!res.ok) {
    let msg = `Request failed: ${res.status}`;
    try { msg = (await res.json()).message || msg; } catch {}
    throw new Error(msg);
  }
  return res.json();
}

// **Autentificare / Înregistrare**
export function login(body) {
  return request('/users/login', { method: 'POST', body: JSON.stringify(body) });
}
export function register(body) {
  return request('/users/register', { method: 'POST', body: JSON.stringify(body) });
}

// **Întrebări**
export function getQuestions() {
  return request('/questions');
}
export function getQuestionById(id) {
  return request(`/questions/${id}`);
}
export function postQuestion(question) {
  return request('/questions', { method: 'POST', body: JSON.stringify(question) });
}

// **Răspunsuri**
export function getAnswersByQuestionId(id) {
  return request(`/answers/question/${id}`);
}
export function postAnswer(answer) {
  // aici answer trebuie să conţină { text, question: { id }, user: { id } }
  return request('/answers', { method: 'POST', body: JSON.stringify(answer) });
}
